use std::io::{Read,Write};use spore_core::{cell_part_geometry::NativeCellPart,cell_feature_projection_v1::Transform,cell_feature_first_candidate_v1::{first,Outcome,LocalGeometry}};
fn main()->Result<(),Box<dyn std::error::Error>>{let mut data=Vec::new();std::io::stdin().read_to_end(&mut data)?;if data.len()!=20{return Err("expected 5 cases".into())}let row=|class|NativeCellPart{word_06_is_ffff:false,class,center:[0.;3],matrix_bits:[0;9],radius:1.,tail_bits:[0;3]};let a=row(2);let b=row(3);let transform=|x|Transform{position:[x,0,0],scale:1f32.to_bits(),flags:0,matrix:[0;9]};let mut out=Vec::new();for row in data.chunks_exact(4){let x=u32::from_le_bytes(row.try_into()?);let r=first([&a,&b],[transform(0),transform(x)],[1,2],[2,3],4,0,true).map_err(|e|format!("{e:?}"))?;let mut w=[0u32;22];w[0]=1;w[1]=2;match r{Outcome::Separated=>{},Outcome::SkippedClassOne=>return Err("unexpected skip".into()),Outcome::Pending(c)=>{w[2]=1;w[3]=c.depth;match c.geometry{LocalGeometry::OpaqueSmall=>w[21]=1,LocalGeometry::Nondegenerate{point,normal}=>{w[4..7].copy_from_slice(&point);w[7..10].copy_from_slice(&normal)}}w[10..21].copy_from_slice(&[c.definition_b4[0],c.classes[0],c.indices[0],c.definition_b4[1],c.second_definition_b0,c.relation as u32,c.classes[1],c.indices[1],1,1,1]);}}for v in w{out.extend(v.to_le_bytes())}}std::io::stdout().write_all(&out)?;Ok(())}
